pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 tokenId, uint256 amount, address initiator, address token) public {
        vm.assume(tokenId != 0 && amount != 0);
        vm.assume(initiator != address(0) && token != address(0));
        bytes memory data = "";
        bytes4 s = c.onERC721Received(initiator, token, tokenId, data);
        assertTrue(s == bytes4(0x150b7a02));
    }
}
